/* exports_host.map — what liblorrax_ffi_host.so keeps PRIVATE.
 *
 * The host twin of exports_cuda.map.  READ THAT FILE FIRST: it carries the
 * argument, the measurement table behind the `*lorrax_ffi*` denylist (and
 * why `local: *` crashes five SLATE host cells), and the note on what stays
 * shared and where it is tracked.  The same rule applies here --
 * **LORRAX's own definitions are private to the library that compiled them**
 * -- with one exception, spelled out below.
 *
 * The other half of the L1 fix is not in this file, because it cannot be:
 * the nine `lrx_*` ctypes entry points that cpp/phdf5/api.cc and
 * cpp/slate/context.cc compile into BOTH libraries have to stay in `.dynsym`
 * for Python to bind them, so hiding is not available.  They are
 * disambiguated by RENAMING instead -- cpp/common/c_abi.h's LRX_C_ENTRY
 * appends `_host` on this leg, the same per-library renaming the `*HostFfi`
 * handlers already used -- and `ffi_loader._bind_c_abi` binds the suffixed
 * symbol under the plain Python name at load, so no call site changed.
 */
{
  global:
    /* EXCEPTION to the pattern below, and the reason this file has a
       `global:` clause at all: the build-config stamp is host-only by
       construction (cpp/common/build_config.cc is in
       LORRAX_FFI_HOST_SOURCES and nowhere else), so it collides with
       nothing -- but its NAME contains `lorrax_ffi`, so the denylist would
       take it.  An exact name beats a wildcard in a version script.
       Exported because it is declared as an API: today its
       `scalapack=<0|1>` stamp is read out of .rodata by
       test_so_acceptance.py's check 1, and hiding the symbol would make the
       function permanently unreachable for the runtime report it exists
       for. */
    lorrax_ffi_host_build_config;
  local:
    *lorrax_ffi*;
};
